function getReceptionLabel(work){
 const c=work.rottenTomatoesCritics, a=work.rottenTomatoesAudience;
 if(c!=null&&a!=null){
  if(c>=90&&a>=90)return language==="fi"?"Erittäin myönteinen vastaanotto":"Very positive reception";
  if(c<=50&&a<=50)return language==="fi"?"Heikko vastaanotto":"Poor reception";
  if(Math.abs(c-a)>=25)return language==="fi"?"Jakaa mielipiteitä":"Divisive reception";
  if(c>=75&&a>=75)return language==="fi"?"Myönteinen vastaanotto":"Positive reception";
  return language==="fi"?"Sekalainen vastaanotto":"Mixed reception";
 }
 if(work.imdbRating!=null&&work.imdbRating>=8.5)return language==="fi"?"Erittäin korkea IMDb-arvosana":"Very high IMDb rating";
 if(work.imdbRating!=null&&work.imdbRating>=7.5)return language==="fi"?"Korkea IMDb-arvosana":"High IMDb rating";
 if(work.imdbRating!=null&&work.imdbRating<5)return language==="fi"?"Matala IMDb-arvosana":"Low IMDb rating";
 return language==="fi"?"Arviotiedot puuttuvat":"Ratings unavailable";
}

