// ---------------------------------------------------------------------------
// 3. Storage, language and catalogue filtering helpers.
// Parse storage defensively so malformed data does not break the catalogue.
// ---------------------------------------------------------------------------
function getLocalReviews(){try{return JSON.parse(localStorage.getItem(storageKey)||"[]")}catch{return []}}
const suggestionStorageKey="cultured-vault-suggestions-v1";
function getLocalSuggestions(){try{return JSON.parse(localStorage.getItem(suggestionStorageKey)||"[]")}catch{return []}}
function setLanguage(next){
 if(next!=="fi"&&next!=="en")return;
 language=next;document.documentElement.lang=language;
 // Keep language changes text-only: rich headings use separate spans and <em> elements in HTML.
 document.querySelectorAll("[data-fi][data-en]").forEach(el=>{el.textContent=el.dataset[language]});
 document.querySelectorAll("[data-fi-placeholder][data-en-placeholder]").forEach(el=>{el.placeholder=el.dataset[language+"Placeholder"]});
 document.querySelectorAll("[data-fi-aria-label][data-en-aria-label]").forEach(el=>el.setAttribute("aria-label",el.dataset[language+"AriaLabel"]));
 document.querySelectorAll("option[data-fi][data-en]").forEach(el=>{el.textContent=el.dataset[language]});
 document.getElementById("demo-language").setAttribute("aria-label",language==="fi"?"Switch to English":"Vaihda suomeksi");
 renderCatalogue();renderLocalReviews();renderLocalSuggestions();
}
function getSearchText(work){return [work.title,work.creator,work.country,...work.genres].join(" ").toLocaleLowerCase()}
function filteredWorks(){
 const query=searchInput.value.trim().toLocaleLowerCase();
 let list=works.filter(w=>(activeCategory==="all"||w.type===activeCategory)&&(!query||getSearchText(w).includes(query)));
 const sort=sortSelect.value;
 if(sort==="title"||sort==="featured")list.sort((a,b)=>a.title.localeCompare(b.title,language==="fi"?"fi":"en",{sensitivity:"base"}));
 if(sort==="year")list.sort((a,b)=>(b.year||0)-(a.year||0));
 if(sort==="rating")list.sort((a,b)=>(b.imdbRating||0)-(a.imdbRating||0));
 return list;
}
// ---------------------------------------------------------------------------
// 4. Build catalogue cards. textContent displays data as text instead of
// parsing it as HTML, including any visitor-entered review comments.
// ---------------------------------------------------------------------------
function renderCatalogue(){
  const list=filteredWorks();
  const alphabetNav=document.getElementById("alphabet-nav");
  const numericNav=document.getElementById("numeric-nav");
  const indexStickyShell=document.getElementById("index-sticky-shell");
  const alphabetical=sortSelect.value==="title"||sortSelect.value==="featured";
  grid.replaceChildren();
  document.getElementById("total-count").textContent=works.length;
  document.getElementById("result-count").textContent=ui[language].count(list.length);
  document.getElementById("empty-state").hidden=list.length!==0;
  alphabetNav.replaceChildren();
  numericNav.replaceChildren();
  const showIndex=alphabetical&&list.length>0;
  alphabetNav.hidden=!showIndex;
  numericNav.hidden=!showIndex;
  indexStickyShell.hidden=!showIndex;
  if(alphabetical&&list.length){
    const firstCharacters=list.map(work=>work.title.trim().charAt(0).toLocaleUpperCase(language==="fi"?"fi":"en"));
    const availableLetters=new Set(firstCharacters.filter(first=>/^[A-ZÅÄÖ]$/i.test(first)));
    const availableNumbers=new Set(firstCharacters.filter(first=>/^\d$/.test(first)));
    const letters="ABCDEFGHIJKLMNOPQRSTUVWXYZÅÄÖ".split("");
    const label=document.createElement("span");label.className="alphabet-label";label.textContent=language==="fi"?"Siirry kirjaimeen:":"Jump to letter:";alphabetNav.append(label);
    letters.forEach(letter=>{
      const button=document.createElement("button");button.type="button";button.className="alphabet-link";button.textContent=letter;button.dataset.letter=letter;button.disabled=!availableLetters.has(letter);button.setAttribute("aria-label",(language==="fi"?"Siirry kirjaimeen ":"Jump to letter ")+letter);
      button.addEventListener("click",()=>{const target=document.getElementById("catalogue-letter-"+letter);if(target)target.scrollIntoView({behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth",block:"start"});});
      alphabetNav.append(button);
    });
    const numberLabel=document.createElement("span");numberLabel.className="alphabet-label";numberLabel.textContent=language==="fi"?"Siirry numerolla:":"Jump to number:";numericNav.append(numberLabel);
    "0123456789".split("").forEach(number=>{
      const button=document.createElement("button");button.type="button";button.className="alphabet-link";button.textContent=number;button.dataset.number=number;button.disabled=!availableNumbers.has(number);button.setAttribute("aria-label",(language==="fi"?"Siirry numerolla ":"Jump to number ")+number);
      button.addEventListener("click",()=>{const target=document.getElementById("catalogue-number-"+number);if(target)target.scrollIntoView({behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth",block:"start"});});
      numericNav.append(button);
    });
  }
  let previousGroup="";
  list.forEach(work=>{
   if(alphabetical){
    const first=work.title.trim().charAt(0).toLocaleUpperCase(language==="fi"?"fi":"en");
    const isNumber=/^\d$/.test(first);
    const group=isNumber?"number:"+first:"letter:"+( /^[A-ZÅÄÖ]$/i.test(first)?first:"#");
    if(group!==previousGroup){
      const heading=document.createElement("h3");
      if(isNumber){heading.className="catalogue-number-heading";heading.id="catalogue-number-"+first;heading.textContent=first;heading.setAttribute("aria-label",(language==="fi"?"Numero ":"Number ")+first);}
      else{const letter=group.slice(7);heading.className="catalogue-letter-heading";heading.id="catalogue-letter-"+letter;heading.textContent=letter;heading.setAttribute("aria-label",(language==="fi"?"Kirjain ":"Letter ")+letter);}
      grid.append(heading);previousGroup=group;
    }
   }
   const card=document.createElement("article");card.className="work-card";
   const top=document.createElement("div");top.className="work-card-top";const badge=document.createElement("span");badge.className="media-badge";badge.textContent=typeLabels[language][work.type];const year=document.createElement("span");year.className="work-year";year.textContent=work.year||"—";top.append(badge,year);card.append(top);
   const title=document.createElement("h3");title.textContent=work.title;card.append(title);
   if(work.creator){const creator=document.createElement("p");creator.className="work-creator";creator.textContent=work.creator;card.append(creator);}
   if(work.genres?.length){const genres=document.createElement("div");genres.className="genre-list";work.genres.forEach(g=>{const tag=document.createElement("span");tag.textContent=g;genres.append(tag)});card.append(genres);}
   const rating=document.createElement("div");rating.className="rating-strip";const owner=document.createElement("span");owner.className="owner-score";owner.textContent="✦ "+ui[language].notRated;owner.setAttribute("aria-label",ui[language].owner+": "+ui[language].notRated);const imdb=document.createElement("span");imdb.className="community-score";imdb.textContent=ui[language].imdb+": "+(work.imdbRating==null?"—":work.imdbRating.toFixed(1)+"/10");rating.append(owner,imdb);card.append(rating);const externalRatings=document.createElement("div");externalRatings.className="external-ratings";const rtCritics=document.createElement("span");rtCritics.textContent=ui[language].rtCritics+": "+(work.rottenTomatoesCritics==null?"—":work.rottenTomatoesCritics+"%");const rtAudience=document.createElement("span");rtAudience.textContent=ui[language].rtAudience+": "+(work.rottenTomatoesAudience==null?"—":work.rottenTomatoesAudience+"%");const reception=document.createElement("strong");reception.textContent=ui[language].reception+": "+getReceptionLabel(work);externalRatings.append(rtCritics,rtAudience,reception);card.append(externalRatings);
   const toggle=document.createElement("button");toggle.className="review-toggle";toggle.type="button";toggle.textContent=ui[language].review;toggle.setAttribute("aria-expanded","false");const reviews=document.createElement("div");reviews.hidden=true;toggle.addEventListener("click",()=>{reviews.hidden=!reviews.hidden;toggle.setAttribute("aria-expanded",String(!reviews.hidden));toggle.textContent=reviews.hidden?ui[language].review:ui[language].hide});
   const ownerReview=document.createElement("div");ownerReview.className="local-review";const ownerHeading=document.createElement("strong");ownerHeading.textContent=ui[language].owner;ownerReview.append(ownerHeading);const ownerText=document.createElement("p");ownerText.textContent=ui[language].noReview;ownerReview.append(ownerText);
   const imdbReview=document.createElement("div");imdbReview.className="local-review";const imdbHeading=document.createElement("strong");imdbHeading.textContent=ui[language].imdb;imdbReview.append(imdbHeading);const imdbText=document.createElement("p");imdbText.textContent=work.imdbRating==null?ui[language].imdbMissing:(language==="fi"?"IMDb:n käyttäjäarvio: ":"IMDb user rating: ")+work.imdbRating.toFixed(1)+"/10. "+(language==="fi"?"Lähde: IMDb. Arvosana voi muuttua.":"Source: IMDb. Ratings may change.");imdbReview.append(imdbText);const imdbLink=document.createElement("a");imdbLink.href="https://www.imdb.com/find/?q="+encodeURIComponent(work.title);imdbLink.target="_blank";imdbLink.rel="noopener noreferrer";imdbLink.textContent="IMDb";imdbReview.append(imdbLink);const rtReview=document.createElement("div");rtReview.className="local-review";const rtHeading=document.createElement("strong");rtHeading.textContent="Rotten Tomatoes";rtReview.append(rtHeading);const rtText=document.createElement("p");rtText.textContent=(language==="fi"?"Kriitikot: ":"Critics: ")+(work.rottenTomatoesCritics==null?ui[language].ratingsMissing:work.rottenTomatoesCritics+"%")+" · "+(language==="fi"?"Yleisö: ":"Audience: ")+(work.rottenTomatoesAudience==null?ui[language].ratingsMissing:work.rottenTomatoesAudience+"%");rtReview.append(rtText);const rtLink=document.createElement("a");rtLink.href=work.rottenTomatoesUrl||"https://www.rottentomatoes.com/search?search="+encodeURIComponent(work.title);rtLink.target="_blank";rtLink.rel="noopener noreferrer";rtLink.textContent="Rotten Tomatoes";rtReview.append(rtLink);reviews.append(ownerReview,imdbReview,rtReview);card.append(toggle,reviews);grid.append(card);
  });
}
// ---------------------------------------------------------------------------
// 5. Render this browser's own demo reviews and populate the work selector.
// ---------------------------------------------------------------------------
function renderLocalReviews(){
 const container=document.getElementById("local-review-list");container.replaceChildren();
 const reviews=getLocalReviews();
 reviews.forEach(review=>{
  const work=works.find(w=>w.id===review.id);if(!work)return;
  const item=document.createElement("article");item.className="local-review";
  const heading=document.createElement("strong");heading.textContent=work.title+" · "+ui[language].yourReview+" · "+review.rating+"/10";
  const comment=document.createElement("p");comment.textContent=review.comment|| (language==="fi"?"Ei kommenttia.":"No comment.");
  item.append(heading,comment);container.append(item);
 });
}
function renderLocalSuggestions(){const container=document.getElementById("local-suggestion-list");if(!container)return;container.replaceChildren();getLocalSuggestions().forEach(item=>{const card=document.createElement("article");card.className="local-review";const heading=document.createElement("strong");heading.textContent=item.title+" · "+(typeLabels[language][item.type]||item.type);const details=document.createElement("p");details.textContent=[item.year||"",item.creator||"",item.note||""].filter(Boolean).join(" · ")||(language==="fi"?"Ei lisätietoja.":"No extra details.");card.append(heading,details);container.append(card)});}
function populateReviewSelect(){
 reviewSelect.replaceChildren();
 works.forEach(work=>{const option=document.createElement("option");option.value=work.id;option.textContent=work.title;reviewSelect.append(option)});
}
// ---------------------------------------------------------------------------
// 6. Event handlers for filtering, search, sorting and review submission.
// ---------------------------------------------------------------------------
document.getElementById("category-filters").addEventListener("click",event=>{
 const button=event.target.closest("button[data-category]");if(!button)return;
 activeCategory=button.dataset.category;
 document.querySelectorAll(".filter-chip").forEach(chip=>{const active=chip===button;chip.classList.toggle("is-active",active);chip.setAttribute("aria-pressed",String(active))});
 renderCatalogue();
});
searchInput.addEventListener("input",renderCatalogue);
sortSelect.addEventListener("change",renderCatalogue);
document.getElementById("personal-review-form").addEventListener("submit",event=>{
 event.preventDefault();
 const rating=Number(document.getElementById("review-rating").value);
 const id=reviewSelect.value;const comment=document.getElementById("review-comment").value.trim();
 if(!Number.isFinite(rating)||rating<1||rating>10){return}
 const reviews=getLocalReviews();reviews.push({id,rating,comment,createdAt:new Date().toISOString()});
 try{localStorage.setItem(storageKey,JSON.stringify(reviews));document.getElementById("review-status").textContent=ui[language].saved;document.getElementById("review-comment").value="";renderLocalReviews()}
 catch{document.getElementById("review-status").textContent=language==="fi"?"Selaimen tallennustila ei ole käytettävissä.":"Browser storage is unavailable."}
});

document.getElementById("suggestion-form").addEventListener("submit",event=>{event.preventDefault();const title=document.getElementById("suggestion-title").value.trim();const type=document.getElementById("suggestion-type").value;const yearValue=document.getElementById("suggestion-year").value;const creator=document.getElementById("suggestion-creator").value.trim();const note=document.getElementById("suggestion-note").value.trim();if(!title)return;const existing=[...works.map(w=>w.title.toLocaleLowerCase()),...getLocalSuggestions().map(w=>w.title.toLocaleLowerCase())];if(existing.includes(title.toLocaleLowerCase())){document.getElementById("suggestion-status").textContent=language==="fi"?"Teos löytyy jo katalogista tai ehdotuksista.":"This work is already in the catalogue or suggestions.";return;}const suggestions=getLocalSuggestions();suggestions.push({title,type,year:yearValue?Number(yearValue):null,creator,note,createdAt:new Date().toISOString()});try{localStorage.setItem(suggestionStorageKey,JSON.stringify(suggestions));document.getElementById("suggestion-status").textContent=ui[language].suggestionSaved;event.target.reset();renderLocalSuggestions()}catch{document.getElementById("suggestion-status").textContent=language==="fi"?"Selaimen tallennustila ei ole käytettävissä.":"Browser storage is unavailable."}});
document.getElementById("demo-language").addEventListener("click",()=>setLanguage(language==="fi"?"en":"fi"));
// The portfolio can request that this embedded demo use the same UI language.
// This synchronises presentation only; it does not exchange personal data.
window.addEventListener("message",event=>{
 if(event.data?.type==="portfolio-language")setLanguage(event.data.language);
});
const alphabetJumpInput=document.getElementById("alphabet-jump-input");
alphabetJumpInput.addEventListener("input",()=>{
 const initial=alphabetJumpInput.value.trim().toLocaleUpperCase("fi");
 const isNumber=/^\d$/.test(initial);
 const isLetter=/^[A-ZÅÄÖ]$/.test(initial);
 if(!isNumber&&!isLetter)return;
 sortSelect.value="title";
 renderCatalogue();
 const targetId=isNumber?"catalogue-number-"+initial:"catalogue-letter-"+initial;
 const target=document.getElementById(targetId);
 if(target)target.scrollIntoView({behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth",block:"start"});
});
populateReviewSelect();renderCatalogue();renderLocalReviews();renderLocalSuggestions();
// Request the portfolio language after the embedded page has loaded.
if (window.parent !== window) window.parent.postMessage({type:"remote-job-fit-language-request"},"*");

// ---------------------------------------------------------------------------
// 7. PWA install prompt and service-worker registration.
// ---------------------------------------------------------------------------
let deferredInstallPrompt = null;
const installButton = document.getElementById("install-app");
window.addEventListener("beforeinstallprompt", event => {
 event.preventDefault();
 deferredInstallPrompt = event;
 if (installButton) installButton.hidden = false;
});
if (installButton) {
 installButton.addEventListener("click", async () => {
  if (!deferredInstallPrompt) return;
  deferredInstallPrompt.prompt();
  await deferredInstallPrompt.userChoice;
  deferredInstallPrompt = null;
  installButton.hidden = true;
 });
}
window.addEventListener("appinstalled", () => {
 if (installButton) installButton.hidden = true;
 deferredInstallPrompt = null;
});
// Service workers require HTTPS or localhost and are scoped to this folder only.
if ("serviceWorker" in navigator && (location.protocol === "https:" || location.hostname === "localhost")) {
 window.addEventListener("load", () => {
  navigator.serviceWorker.register("./sw.js", {scope:"./"}).catch(error => {
   console.warn("The Cultured Vault offline support could not be enabled.", error);
  });
 });
}

